SELECT jsonb_build_object('command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id='30000000-0000-4000-8000-000000000003'),'customer',(SELECT count(*) FROM app.customer_profiles WHERE id='20000000-0000-4000-8000-000000000003'),'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE id='40000000-0000-4000-8000-000000000003'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE id='50000000-0000-4000-8000-000000000003'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id='30000000-0000-4000-8000-000000000003'),'coherent',EXISTS(SELECT 1 FROM platform.runtime_command_receipt q
 JOIN app.customer_profiles c ON c.id='20000000-0000-4000-8000-000000000003' AND c.user_id='10000000-0000-4000-8000-000000000002' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
 JOIN app.customer_profile_lifecycle_event h ON h.id='40000000-0000-4000-8000-000000000003' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id AND h.source_revision=0 AND h.actor_user_id=c.user_id AND h.from_status IS NULL AND h.to_status='active'
 JOIN platform.owner_mutation_evidence e ON e.id='50000000-0000-4000-8000-000000000003' AND e.command_receipt_id=q.id AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.committed_revision=0 AND e.previous_revision IS NULL AND e.owner_module_id=q.owner_module_id
 WHERE q.id='30000000-0000-4000-8000-000000000003' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1' AND q.subject_scope='CustomerProfile:'||c.id::text AND q.state='committed' AND q.source_revision=0
 AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex') AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
 AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0
  AND o.mutation_transaction_id=c.mutation_transaction_id AND o.payload->>'userId'=c.user_id::text AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
  AND ((o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1') OR (o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1')))=2),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='20000000-0000-4000-8000-000000000003'));
